// research: 'two-sided trading' is a design decision, not a stated formula; candidate clues from the text
overlapScore = fractionOfLastNBarsOverlapping(overlapLookback, minOverlapFraction);
swingCount = countDirectionChanges(swingLookback);
maSlopeFlat = abs(maSlope(maLookback)) <= flatSlopeThreshold;
isTradingRange = combineClues(overlapScore, swingCount, maSlopeFlat); // exact combination left to the authoring pass

// requires trend-line slope from the range's containing lines
rangeLineSlope = slopeOfLine(rangeBoundaryPivots);
isStillTradingRange = abs(rangeLineSlope) <= maxTradingRangeSlope;

// requires swing-pivot detection for the reference swing low
brokeSwingLow = low[1] < recentSwingLow;
reversedNextBar = close[0] > recentSwingLow && close[0] > open[0];
isStopRunReversal = brokeSwingLow && reversedNextBar;

overlapAmount = min(high[0], high[1]) - max(low[0], low[1]);
overlapFraction = overlapAmount / (high[1] - low[1] + epsilon);
isOverlappingBar = overlapFraction >= overlapThreshold;
consecutiveOverlapCount = countConsecutiveOverlappingBars(overlapThreshold);

spikeBrokeRangeHigh = high[k] > rangeHigh; // some recent bar k spiked above the range top
failedAndReversed = barsSinceSpike <= maxReversalBars && close[0] < rangeHigh && close[0] < open[0];
enterShortNextBarOpen = isTradingRange[0] && spikeBrokeRangeHigh && failedAndReversed;

// depends on High1/High2/Low1/Low2 signal primitives assumed defined elsewhere in the corpus
distanceFromRangeBottom = close[0] - rangeLow;
isNearRangeBottom = distanceFromRangeBottom <= (rangeHigh - rangeLow) * nearExtremeFraction;
validHigh2Buy = isTradingRange[0] && isHigh2Signal[0] && isNearRangeBottom;
distanceFromRangeTop = rangeHigh - close[0];
isNearRangeTop = distanceFromRangeTop <= (rangeHigh - rangeLow) * nearExtremeFraction;
fadeableHigh2AtTop = isTradingRange[0] && isHigh2Signal[0] && isNearRangeTop; // candidate short-fade, mirrored logic for Low1/Low2

isChannelNotSpike = legMoveClassification(finalLegDown) == CHANNEL; // as opposed to SPIKE
isRangeBottomReversal = isTradingRange[1] && isChannelNotSpike && low[1] <= rangeLow + rangeLowTolerance && close[0] > open[0] && close[0] > high[1];
enterLongNextBarOpen = isRangeBottomReversal;

signalBarRange = high[1] - low[1];
averageRecentRange = average(high - low, avgRangeLookback);
isSignalBarAcceptableSize = signalBarRange <= maxSignalBarRangeMultiple * averageRecentRange;

// research: the choice between the aggressive close-fade and the conservative stop-entry is left to trader experience, with no bar-level test distinguishing the two
useAggressiveCloseFade = traderExperienceLevel >= experiencedThreshold;
useConservativeStopEntry = !useAggressiveCloseFade;

// research: 'clearly started to resume' has no bar-level definition given (ties to an 'always-in' judgment)
allowBreakoutEntry = trendClearlyResuming[0];
enterLongOnBreakoutStop = allowBreakoutEntry && high[0] >= (rangeHigh + entryTick);

isMicroChannel = isTightChannel(recentLeg, maxBarRangeForMicroChannel, minOverlapFraction);
skipDirectFade = isMicroChannel;
waitForBreakoutPullback = skipDirectFade;

tailCount = countBarsWithTail(side = TOP, lookback = pressureLookback, minTailFraction);
strongBodyCount = countBarsWithStrongBody(side = BEAR, lookback = pressureLookback, minBodyFraction);
hasConfirmingPressure = tailCount >= minPressureBars || strongBodyCount >= minPressureBars;

isMiddleThirdOfDay = time[0] >= middleThirdStartTime && time[0] <= middleThirdEndTime;
dayRangeMidpoint = (dayHigh + dayLow) / 2;
isNearDayRangeMiddle = abs(close[0] - dayRangeMidpoint) <= (dayHigh - dayLow) * middleZoneFraction;
avoidMarginalEntries = isMiddleThirdOfDay && isNearDayRangeMiddle;

// depends on a climax/spike primitive assumed defined elsewhere in the corpus
isClimaxReversal = isSpike(priorLeg, direction = UP) && isSpike(currentLeg, direction = DOWN) && legsAreAdjacent(priorLeg, currentLeg);
expectTradingRangeTransition = isClimaxReversal[0];

// depends on a climax primitive assumed defined elsewhere in the corpus
consecutiveClimaxCount = countConsecutiveClimaxes(direction = DOWN, maxGapBars = climaxGapBars);
expectSignificantPullback = consecutiveClimaxCount >= minConsecutiveClimaxes;

// requires swing-pivot detection
trailingStopPrice = mostRecentSwingLow - trailBuffer;
exitLongOnStop = low[0] <= trailingStopPrice;

// research: 'always-in flips to long' is the MINING.md canonical research example; no bar-level test is given for the flip itself
alwaysInDirection = alwaysInDirection[0]; // design-decision output, e.g. sign of a persistent state variable
justFlippedToLong = alwaysInDirection == LONG && alwaysInDirection[1] != LONG;
enterLongAtMarketOrMinorPullback = justFlippedToLong;

spikeHeight = spikeEndPrice - spikeStartPrice;
measuredMoveTarget = spikeEndPrice + spikeHeight;
exitLongAtTarget = high[0] >= measuredMoveTarget;
